console.log('[md-insert-audio] Script loaded'); document.addEventListener('DOMContentLoaded', function () { console.log('[md-insert-audio] DOM ready'); let audioModal = null; let audioListContainer = document.getElementById('audioList'); let uploadForm = document.getElementById('uploadAudioForm'); let uploadBtn = document.getElementById('uploadAudioBtn'); let uploadStatus = document.getElementById('uploadAudioStatus'); let audioUrlInput = document.getElementById('audioUrlInput'); let insertUrlAudioBtn = document.getElementById('insertUrlAudioBtn'); let selectedTextarea = null; function initModal() { if (!audioModal && document.getElementById('insertAudioModal')) { console.log('[md-insert-audio] Initializing modal'); audioModal = new bootstrap.Modal(document.getElementById('insertAudioModal')); } } function getCurrentCSRFToken() { let metaTag = document.querySelector('meta[name="csrf_token"]'); return metaTag ? metaTag.getAttribute('content') : ''; } document.addEventListener('md-mini:insert-audio', function (e) { console.log('[md-insert-audio] Insert audio event triggered'); initModal(); selectedTextarea = e.detail.textarea; console.log('[md-insert-audio] Textarea:', selectedTextarea ? 'found' : 'not found'); if (audioModal) { loadAudios(); audioModal.show(); } else { console.error('[md-insert-audio] Modal not initialized'); } }); function loadAudios() { console.log('[md-insert-audio] Loading audios'); if (!audioListContainer) { console.error('[md-insert-audio] audioListContainer not found'); return } fetch('/api/audios', { method: 'GET', headers: { 'Content-Type': 'application/json' } }).then(r => { console.log('[md-insert-audio] Response status:', r.status); if (r.status === 401) { console.log('[md-insert-audio] Not authenticated'); audioListContainer.innerHTML = '<div class="alert alert-info mb-0">Faça login para usar este recurso</div>'; return [] } return r.json(); }).then(audios => { console.log('[md-insert-audio] Loaded', audios ? audios.length : 0, 'audios'); if (!audios || audios.length === 0) { audioListContainer.innerHTML = '<div class="text-center text-body-secondary py-4"><small>Nenhum áudio disponível. Faça upload de um novo.</small></div>'; return } let html = ''; audios.forEach(audio => { html += '<div class="mb-3 p-2" style="border-bottom: 1px solid var(--bs-border-color);">'; html += '<div class="mb-2"><strong>' + escapeHtml(audio.display_name) + '</strong></div>'; html += '<audio style="max-width: 100%; width: 100%; margin-bottom: 0.5rem;" controls><source src="' + escapeHtml(audio.file_url) + '"></audio>'; if (audio.description) { html += '<div class="small text-body-secondary mb-2">' + escapeHtml(audio.description) + '</div>'; } html += '<div class="d-flex gap-2">'; html += '<button type="button" class="btn btn-sm btn-outline-primary select-audio-btn" data-url="' + escapeHtml(audio.file_url) + '" data-name="' + escapeHtml(audio.display_name) + '">Inserir</button>'; html += '<small class="text-body-secondary align-self-center">' + escapeHtml(audio.created_at || '') + '</small>'; html += '</div>'; html += '</div>'; }); audioListContainer.innerHTML = html; document.querySelectorAll('.select-audio-btn').forEach(btn => { btn.addEventListener('click', function () { insertAudio(this.getAttribute('data-url'), this.getAttribute('data-name')); }); }); }).catch(err => { console.error('[md-insert-audio] Error loading audios:', err); audioListContainer.innerHTML = '<div class="alert alert-danger mb-0">Erro ao carregar áudios: ' + err + '</div>'; }); } if (uploadForm) { uploadForm.addEventListener('submit', function (e) { e.preventDefault(); let file = document.getElementById('audioFileInput').files[0]; if (!file) { uploadStatus.innerHTML = '<div class="alert alert-warning mb-0">Selecione um áudio</div>'; return } console.log('[md-insert-audio] Uploading audio:', file.name); uploadStatus.innerHTML = '<div class="alert alert-info mb-0">Enviando...</div>'; uploadBtn.disabled = true; let formData = new FormData(); formData.append('file', file); formData.append('original_filename', file.name); formData.append('description', document.getElementById('audioDescription').value || file.name); formData.append('filetag', 'forum'); formData.append('csrf_token', getCurrentCSRFToken()); fetch('/files/upload', { method: 'POST', body: formData }).then(r => r.text()).then(html => { console.log('[md-insert-audio] Upload response received, length:', html.length); if (html.indexOf('alert-danger') !== -1 || html.indexOf('error') !== -1 || html.indexOf('Error') !== -1) { console.error('[md-insert-audio] Upload error in response'); uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload. Verifique o tamanho do arquivo (máx. 500 MB).</div>'; } else { console.log('[md-insert-audio] Upload successful'); uploadStatus.innerHTML = '<div class="alert alert-success mb-0">Upload concluído. Recarregando lista...</div>'; document.getElementById('audioFileInput').value = ''; document.getElementById('audioDescription').value = ''; setTimeout(function () { loadAudios(); uploadStatus.innerHTML = ''; }, 1500); } }).catch(err => { console.error('[md-insert-audio] Upload error:', err); uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload: ' + err + '</div>'; }).finally(() => { uploadBtn.disabled = false; }); }); } if (insertUrlAudioBtn) { insertUrlAudioBtn.addEventListener('click', function () { let url = audioUrlInput.value.trim(); if (!url) { console.warn('[md-insert-audio] Empty URL'); return } insertAudio(url, 'Áudio'); }); } function insertAudio(url, name) { console.log('[md-insert-audio] Inserting audio:', url); if (!selectedTextarea) { console.error('[md-insert-audio] No textarea selected'); return } let markdown = '<audio style="max-width: 100%; width: 100%;" controls><source src="' + url + '" type="audio/mpeg"></audio>'; selectedTextarea.value += '\n' + markdown; selectedTextarea.dispatchEvent(new Event('change', { bubbles: true })); console.log('[md-insert-audio] Audio markdown inserted'); if (audioModal) audioModal.hide(); } function escapeHtml(text) { if (!text) return ''; let map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }; return text.replace(/[&<>"']/g, m => map[m]); } });
